{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Cyanidin-3-O-glucoside, a highly polar polyphenolic glycoside, was detected in rat brain after intravenous administration and in human brain vascular endothelium, directly demonstrating that this structural class can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Intact cyanidin 3-galactoside was found in pig brain, supporting transfer of anthocyanin glycosides across the BBB in a large-animal model.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Rutin and hyperoside, neutral flavonoid O-glycosides, were detected in rat brain after oral administration, showing that flavonoid glycosides reach the CNS after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Cyanidin-3-O-glucoside reached approximately 3.5 nmol/g in mouse brain after intraperitoneal injection, providing quantitative evidence of meaningful brain exposure for a glycoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Hydroxysafflor yellow A, a highly polar C-glycoside, reached 1026 ng/g in rat brain, directly supporting CNS access for C-glycosylated polyphenols similar to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Astragalin, a flavonol 3-O-glucoside, transferred across the BBB in rat tissue distribution analysis, further supporting brain penetration of flavonoid glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Tiazofurin, a C-nucleoside with a ribose and polar heterocycle, was detected in rat brain after intraperitoneal injection, supporting CNS access for C-glycoside-like molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Despite unfavorable passive-diffusion predictions, multiple structurally related flavonoid glycosides and C-glycosides are directly detected in brain after systemic administration, indicating meaningful CNS access for the query luteolin C-glucoside.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF quantification for the exact luteolin C-glucoside query; most evidence is qualitative brain detection.",
    "Some studies may reflect metabolites rather than exclusively intact glycosides, though several report intact compounds.",
    "Efflux transporter involvement is not quantitatively defined for the query, but the endpoint does not require absence of efflux.",
    "Species differences and lack of human quantitative data for the exact query remain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

